package api

import (
	"context"
	"encoding/json"
	"net/http"
	"slices"
	"strconv"
	"testing"
	"time"

	"github.com/go-chi/chi/v5"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/store"
)

// TestHandlersThreadViewer is the 6.2 threading matrix, black-box over the
// real route mount: every content-read handler (libraries, items, series
// reads, progress, the scored-ordering path) passes its REQUESTING viewer to
// the store — proven through the two seams the role tests own. The env-admin
// principal keeps today's legacy shape (all libraries, all items, all
// ledger slots); an injected scoped principal (principalViewerInjector — the
// carrier viewerFor memoizes) sees only its granted libraries on every one
// of those surfaces, and its writes stamp its OWN ledger slot.
func TestHandlersThreadViewer(t *testing.T) {
	st := openAPIStore(t)
	ctx := context.Background()

	lib1, err := st.CreateLibrary(ctx, "tv", "/media/one", "One")
	if err != nil {
		t.Fatalf("CreateLibrary lib1: %v", err)
	}
	lib2, err := st.CreateLibrary(ctx, "film", "/media/two", "Two")
	if err != nil {
		t.Fatalf("CreateLibrary lib2: %v", err)
	}
	const itemOne = "itm_one"
	const itemTwo = "itm_two"
	seedItem := func(id, fid string, lib int64) {
		t.Helper()
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "tv", LibraryID: lib, FileID: fid,
			RelativePath: fid + ".mkv", MediaType: "tv",
			Document: json.RawMessage(`{}`), SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}
	seedItem(itemOne, "fid-one", lib1)
	seedItem(itemTwo, "fid-two", lib2)

	// The legacy slot-0 ledger (System writes): a position on both items and
	// a completion on the UNgranted item — the scoped viewer below must never
	// see any of it.
	seedLegacy := func(itemID string, pos int64) {
		t.Helper()
		if _, err := st.PutProgress(ctx, itemID, pos, access.System()); err != nil {
			t.Fatalf("PutProgress legacy %s: %v", itemID, err)
		}
	}
	seedLegacy(itemOne, 100)
	seedLegacy(itemTwo, 200)
	if err := st.InsertWatched(ctx, itemTwo, lib2, "", time.Now().UTC(), access.System()); err != nil {
		t.Fatalf("InsertWatched legacy: %v", err)
	}

	// The scoped principal's OWN slot-42 rows on BOTH items: the granted
	// item's row is readable, the ungranted item's row is dead weight the
	// visibility conjunct must bury — the exact revoked-grant posture. The
	// seeding writes ride the two-grant viewer (both libraries visible at
	// write time; the grants narrow AFTER, which is the revoked-grant story).
	scopedWriter := access.User(42, []int64{lib1, lib2}, nil)
	if _, err := st.PutProgress(ctx, itemOne, 50, scopedWriter); err != nil {
		t.Fatalf("PutProgress scoped %s: %v", itemOne, err)
	}
	if _, err := st.PutProgress(ctx, itemTwo, 150, scopedWriter); err != nil {
		t.Fatalf("PutProgress scoped %s: %v", itemTwo, err)
	}

	router := func(mws ...func(http.Handler) http.Handler) http.Handler {
		h := &app{deps: Deps{Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		}}}
		r := chi.NewRouter()
		for _, mw := range mws {
			r.Use(mw)
		}
		r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
		return r
	}
	// The scoped seam rides the CLIENT principal (authZ admits it) with the
	// viewer injected on the carrier — viewerFor memoizes the stash, so the
	// principal mapping never overrides the seeded scope.
	scopedRouter := func(scope access.Viewer) http.Handler {
		return router(principalInjector(RoleClient), principalViewerInjector(scope))
	}

	libraryIDs := func(t *testing.T, h http.Handler, path string) []int64 {
		t.Helper()
		resp := doRequest(t, h, http.MethodGet, path, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("%s: status = %d, want 200", path, resp.StatusCode)
		}
		var lr librariesResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("%s: decode librariesResponse: %v", path, err)
		}
		ids := make([]int64, len(lr.Items))
		for i, l := range lr.Items {
			ids[i] = l.ID
		}
		return ids
	}
	itemIDs := func(t *testing.T, h http.Handler, path string) []string {
		t.Helper()
		resp := doRequest(t, h, http.MethodGet, path, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("%s: status = %d, want 200", path, resp.StatusCode)
		}
		var ir itemsResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("%s: decode itemsResponse: %v", path, err)
		}
		ids := make([]string, len(ir.Items))
		for i, it := range ir.Items {
			ids[i] = it.ID
		}
		return ids
	}
	progressItems := func(t *testing.T, h http.Handler, path string) []string {
		t.Helper()
		resp := doRequest(t, h, http.MethodGet, path, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("%s: status = %d, want 200", path, resp.StatusCode)
		}
		var pr progressListResponse
		if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
			t.Fatalf("%s: decode progressListResponse: %v", path, err)
		}
		ids := make([]string, len(pr.Items))
		for i, p := range pr.Items {
			ids[i] = p.ItemID
		}
		return ids
	}

	t.Run("env_admin_sees_all", func(t *testing.T) {
		h := router(principalInjector(RoleAdmin))
		// Libraries: both, unchanged legacy shape.
		got := libraryIDs(t, h, "/api/v1/libraries")
		for _, want := range []int64{lib1, lib2} {
			if !slices.Contains(got, want) {
				t.Fatalf("admin libraries = %v, want both %d and %d", got, lib1, lib2)
			}
		}
		// Items: the granted-vs-scoped split never shows for admin.
		if got := itemIDs(t, h, "/api/v1/items?library="+strconv.FormatInt(lib1, 10)); !slices.Equal(got, []string{itemOne}) {
			t.Fatalf("admin items lib1 = %v, want [%s]", got, itemOne)
		}
		if got := itemIDs(t, h, "/api/v1/items?library="+strconv.FormatInt(lib2, 10)); !slices.Equal(got, []string{itemTwo}) {
			t.Fatalf("admin items lib2 = %v, want [%s]", got, itemTwo)
		}
		// Progress: admin reads across every slot (the rail lists the same
		// item once per readable slot), and the withdrawal default
		// (watched-states D2 — unchanged legacy shape) still drops the
		// ledgered itemTwo unless ?include=watched restores it.
		rail := progressItems(t, h, "/api/v1/progress")
		if !slices.Contains(rail, itemOne) || slices.Contains(rail, itemTwo) {
			t.Fatalf("admin scored progress = %v, want %s present and watched %s withdrawn", rail, itemOne, itemTwo)
		}
		recent := progressItems(t, h, "/api/v1/progress?include=watched&sort=recent")
		for _, want := range []string{itemOne, itemTwo} {
			if !slices.Contains(recent, want) {
				t.Fatalf("admin recent+watched progress = %v, want %s present (all slots)", recent, want)
			}
		}
		// The legacy write posture: the env-admin PUT lands in the slot-0
		// ledger (the viewer the handler threaded stamps Admin → slot 0).
		resp := doRequest(t, h, http.MethodPut, "/api/v1/progress/"+itemOne, `{"position_seconds": 111}`, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("admin PUT progress: status = %d, want 200", resp.StatusCode)
		}
		rec, err := st.GetProgress(ctx, itemOne, access.System())
		if err != nil {
			t.Fatalf("GetProgress slot-0 read-back: %v", err)
		}
		if rec.PositionSeconds != 111 {
			t.Fatalf("admin PUT landed at position %d in slot 0, want 111", rec.PositionSeconds)
		}
		// The media route's GetItem is threaded too: admin resolves the item
		// and walks its (empty) document — the 404 names the missing fact,
		// not the item.
		resp = doRequest(t, h, http.MethodGet, "/api/v1/items/"+itemTwo+"/media", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("admin media status = %d, want 404", resp.StatusCode)
		}
		if eb := decodeError(t, resp); eb.Error.Message != "item "+itemTwo+" carries no media path fact" {
			t.Fatalf("admin media message = %q, want the document-walk floor (item resolved, fact absent)", eb.Error.Message)
		}
	})

	t.Run("scoped_viewer_sees_granted_only", func(t *testing.T) {
		h := scopedRouter(access.User(42, []int64{lib1}, nil))
		// Libraries: the granted one only.
		if got := libraryIDs(t, h, "/api/v1/libraries"); !slices.Equal(got, []int64{lib1}) {
			t.Fatalf("scoped libraries = %v, want [%d] only", got, lib1)
		}
		// Items — the scored default (allFilteredItems + recsFactsFor's
		// ledger reads) and the sort=path opt-out (QueryItems direct).
		if got := itemIDs(t, h, "/api/v1/items?library="+strconv.FormatInt(lib1, 10)); !slices.Equal(got, []string{itemOne}) {
			t.Fatalf("scoped items lib1 = %v, want [%s]", got, itemOne)
		}
		if got := itemIDs(t, h, "/api/v1/items?library="+strconv.FormatInt(lib2, 10)); len(got) != 0 {
			t.Fatalf("scoped items lib2 = %v, want empty (library not granted)", got)
		}
		if got := itemIDs(t, h, "/api/v1/items?library="+strconv.FormatInt(lib2, 10)+"&sort=path"); len(got) != 0 {
			t.Fatalf("scoped items lib2 sort=path = %v, want empty", got)
		}
		// Detail reads: the granted item resolves, the ungranted one is an
		// unknown item.
		for _, tc := range []struct {
			path string
			want int
		}{
			{"/api/v1/items/" + itemOne, http.StatusOK},
			{"/api/v1/items/" + itemTwo, http.StatusNotFound},
			{"/api/v1/progress/" + itemOne, http.StatusOK},
			{"/api/v1/progress/" + itemTwo, http.StatusNotFound},
		} {
			resp := doRequest(t, h, http.MethodGet, tc.path, "", adminToken)
			if resp.StatusCode != tc.want {
				resp.Body.Close()
				t.Fatalf("GET %s: status = %d, want %d", tc.path, resp.StatusCode, tc.want)
			}
			resp.Body.Close()
		}
		// Progress, BOTH orders: only the viewer's OWN readable row surfaces
		// — the slot-0 legacy rows are another slot's, the ungranted item's
		// own-slot row is buried by the visibility conjunct, and the
		// ungranted completion never enters the scored facts.
		if got := progressItems(t, h, "/api/v1/progress"); !slices.Equal(got, []string{itemOne}) {
			t.Fatalf("scoped progress (scored) = %v, want [%s] only", got, itemOne)
		}
		if got := progressItems(t, h, "/api/v1/progress?sort=recent"); !slices.Equal(got, []string{itemOne}) {
			t.Fatalf("scoped progress (recent) = %v, want [%s] only", got, itemOne)
		}
		// The scoped write stamps the viewer's OWN slot: the PUT lands at
		// (42, itemOne), and the ungranted item's PUT is a 404 that writes
		// nothing (hidden ≡ unknown — no orphan, no slot-42 overwrite).
		resp := doRequest(t, h, http.MethodPut, "/api/v1/progress/"+itemOne, `{"position_seconds": 123}`, adminToken)
		if resp.StatusCode != http.StatusOK {
			resp.Body.Close()
			t.Fatalf("scoped PUT progress: status = %d, want 200", resp.StatusCode)
		}
		resp.Body.Close()
		rec, err := st.GetProgress(ctx, itemOne, scopedWriter)
		if err != nil {
			t.Fatalf("GetProgress slot-42 read-back: %v", err)
		}
		if rec.PositionSeconds != 123 {
			t.Fatalf("scoped PUT landed at position %d in slot 42, want 123", rec.PositionSeconds)
		}
		resp = doRequest(t, h, http.MethodPut, "/api/v1/progress/"+itemTwo, `{"position_seconds": 999}`, adminToken)
		if resp.StatusCode != http.StatusNotFound {
			resp.Body.Close()
			t.Fatalf("scoped PUT ungranted: status = %d, want 404", resp.StatusCode)
		}
		resp.Body.Close()
		if rec, err := st.GetProgress(ctx, itemTwo, scopedWriter); err == nil && rec.PositionSeconds == 999 {
			t.Fatalf("scoped PUT wrote %d into the ungranted item's slot-42 row (write must refuse)", rec.PositionSeconds)
		}
		// The media route is threaded: the ungranted item is an unknown item
		// — the 404 names the item, not a document fact.
		resp = doRequest(t, h, http.MethodGet, "/api/v1/items/"+itemTwo+"/media", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("scoped media status = %d, want 404", resp.StatusCode)
		}
		if eb := decodeError(t, resp); eb.Error.Message != "item "+itemTwo+" not found" {
			t.Fatalf("scoped media message = %q, want the not-found floor (store read scoped)", eb.Error.Message)
		}
	})

	t.Run("second_grant_appears", func(t *testing.T) {
		h := scopedRouter(access.User(42, []int64{lib1, lib2}, nil))
		got := libraryIDs(t, h, "/api/v1/libraries")
		slices.Sort(got)
		want := []int64{lib1, lib2}
		slices.Sort(want)
		if !slices.Equal(got, want) {
			t.Fatalf("two-grant libraries = %v, want both %v", got, want)
		}
		// The previously hidden ledger row surfaces with the grant: the
		// slot-42 row on the now-granted item joins the rail (order is the
		// store's updated_at window — asserted as a set).
		ownRows := progressItems(t, h, "/api/v1/progress?sort=recent")
		slices.Sort(ownRows)
		wantRows := []string{itemOne, itemTwo}
		if !slices.Equal(ownRows, wantRows) {
			t.Fatalf("two-grant progress = %v, want exactly %v (own-slot rows only)", ownRows, wantRows)
		}
	})
}
